package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

/** Complete winner cost of subqueries embedded in scalar expressions. */
@PackedHotPath
final class PackedDependentSubqueryCosting {

	/*
	 * A subquery whose winner consumes outer bindings is re-evaluated once per row of the owning operator's input, not
	 * once per query. Charging its winner cost a single time made a correlated EXISTS probe look cheaper than any
	 * bounded alternative regardless of how many rows re-open it (the 2026-07 benchmark-timeout family). An
	 * outer-independent subquery is still charged once: its result is computable up front and shared.
	 */
	static final String CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY = "rdf4j.optimizer.packed.correlatedDependentInvocations";

	private PackedDependentSubqueryCosting() {
	}

	static double defaultCost(PackedQuery query, PackedMemo memo, int relationId, double expectedInvocations) {
		return scalarCost(query, memo, conditionId(query, relationId), 0,
				query.relOutputMaskId(relationId), expectedInvocations);
	}

	static double contextualCost(PackedQuery query, PackedMemo memo, int relationId, int[] prefixRelations,
			double[] prefixContributionRows, int prefixCount, double prefixRows, int prefixEvidenceStateId,
			int bindingLayoutId, int correlationMaskId, int semanticScopeMaskId, double expectedInvocations) {
		int inputContextId = memo.internEvidenceContext(prefixRelations, prefixContributionRows, 0, prefixCount,
				prefixRows, prefixEvidenceStateId, bindingLayoutId, correlationMaskId, semanticScopeMaskId);
		return scalarCost(query, memo, conditionId(query, relationId), inputContextId,
				query.relOutputMaskId(relationId), expectedInvocations);
	}

	static void publishDefaultPlanInputs(PackedQuery query, PackedMemo memo, int relationId,
			PackedCostEstimate destination) {
		publishScalarPlanInputs(query, memo, conditionId(query, relationId), 0,
				query.relOutputMaskId(relationId), destination);
	}

	static void publishContextualPlanInputs(PackedQuery query, PackedMemo memo, int relationId,
			int[] prefixRelations, double[] prefixContributionRows, int prefixCount, double prefixRows,
			int prefixEvidenceStateId, int bindingLayoutId, int correlationMaskId, int semanticScopeMaskId,
			PackedCostEstimate destination) {
		int inputContextId = memo.internEvidenceContext(prefixRelations, prefixContributionRows, 0, prefixCount,
				prefixRows, prefixEvidenceStateId, bindingLayoutId, correlationMaskId, semanticScopeMaskId);
		publishScalarPlanInputs(query, memo, conditionId(query, relationId), inputContextId,
				query.relOutputMaskId(relationId), destination);
	}

	static void recordContextualPlans(PackedQuery query, PackedMemo memo, int ownerWinnerId, int relationId,
			int[] prefixRelations, double[] prefixContributionRows, int prefixCount, double prefixRows,
			int prefixEvidenceStateId, int bindingLayoutId, int correlationMaskId, int semanticScopeMaskId) {
		int inputContextId = memo.internEvidenceContext(prefixRelations, prefixContributionRows, 0, prefixCount,
				prefixRows, prefixEvidenceStateId, bindingLayoutId, correlationMaskId, semanticScopeMaskId);
		recordScalarPlans(query, memo, ownerWinnerId, conditionId(query, relationId), inputContextId);
	}

	private static int conditionId(PackedQuery query, int relationId) {
		return switch (query.relOperator(relationId)) {
		case PackedRelOp.FILTER -> query.relPayload(relationId);
		case PackedRelOp.SEMI_JOIN, PackedRelOp.ANTI_JOIN -> query.payloadPrimary(query.relPayload(relationId));
		default -> 0;
		};
	}

	private static double scalarCost(PackedQuery query, PackedMemo memo, int scalarId, int inputContextId,
			int outerBindingMaskId, double expectedInvocations) {
		if (scalarId == 0) {
			return 0.0d;
		}
		double cost = 0.0d;
		if (query.scalarOperator(scalarId) == PackedScalarOp.EXISTS) {
			int payloadId = query.scalarPayload(scalarId);
			if (query.payloadOperator(payloadId) == PackedPayloadOp.SUBQUERY_VALUE
					&& query.payloadChildCount(payloadId) == 1) {
				int subqueryRelationId = query.payloadChild(payloadId, 0);
				int groupId = memo.logicalGroupId(subqueryRelationId);
				int contextualWinnerId = inputContextId == 0
						? 0
						: memo.findWinner(groupId, memo.anyPropertyId(), 0, inputContextId, 0);
				int winnerId = contextualWinnerId == 0
						? memo.findWinner(groupId, memo.anyPropertyId(), 0, 0, 0)
						: contextualWinnerId;
				if (winnerId == 0) {
					throw new PackedMemoInvariantException(
							"embedded subquery " + subqueryRelationId + " has no incumbent");
				}
				cost = memo.winnerTotalCost(winnerId);
				double pricedInvocations = 1.0d;
				int metadataId = memo.winnerPhysicalMetadataId(winnerId);
				if (metadataId != 0) {
					double explicitInvocations = memo.physicalMetadataInvocations(metadataId);
					if (Double.isFinite(explicitInvocations) && explicitInvocations > 0.0d) {
						pricedInvocations = explicitInvocations;
					}
				}
				double remainingInvocations = expectedInvocations / pricedInvocations;
				if (Double.isFinite(remainingInvocations) && remainingInvocations > 1.0d
						&& memo.winnerDependsOnOuterBindings(winnerId, outerBindingMaskId)) {
					/*
					 * Without a complete component profile, exempt at most the constant setup unit and repeat all
					 * remaining traversal. An explicit invocation stamp records how much of the required domain this
					 * winner already priced, so contextual plans are neither double-charged nor assumed complete merely
					 * because their output rows are contextual.
					 */
					double startupOnce = Math.min(cost,
							Math.min(1.0d, Math.max(0.0d, memo.winnerStartupCost(winnerId))));
					double nonStartupWork = Math.max(0.0d, cost - startupOnce);
					cost = saturatedAdd(startupOnce, saturatedMultiply(nonStartupWork, remainingInvocations));
				}
			}
		}
		for (int ordinal = 0; ordinal < query.scalarChildCount(scalarId); ordinal++) {
			cost = saturatedAdd(cost,
					scalarCost(query, memo, query.scalarChild(scalarId, ordinal), inputContextId,
							outerBindingMaskId, expectedInvocations));
		}
		return cost;
	}

	private static void publishScalarPlanInputs(PackedQuery query, PackedMemo memo, int scalarId, int inputContextId,
			int outerBindingMaskId, PackedCostEstimate destination) {
		if (scalarId == 0) {
			return;
		}
		if (query.scalarOperator(scalarId) == PackedScalarOp.EXISTS) {
			int payloadId = query.scalarPayload(scalarId);
			if (query.payloadOperator(payloadId) == PackedPayloadOp.SUBQUERY_VALUE
					&& query.payloadChildCount(payloadId) == 1) {
				int subqueryRelationId = query.payloadChild(payloadId, 0);
				int winnerId = selectedWinner(query, memo, subqueryRelationId, inputContextId);
				if (winnerId != 0) {
					memo.publishDependentPlanInput(winnerId, outerBindingMaskId, destination);
				}
			}
		}
		for (int ordinal = 0; ordinal < query.scalarChildCount(scalarId); ordinal++) {
			publishScalarPlanInputs(query, memo, query.scalarChild(scalarId, ordinal), inputContextId,
					outerBindingMaskId, destination);
		}
	}

	private static int selectedWinner(PackedQuery query, PackedMemo memo, int subqueryRelationId,
			int inputContextId) {
		int groupId = memo.logicalGroupId(subqueryRelationId);
		int winnerId = inputContextId == 0
				? 0
				: memo.findWinner(groupId, memo.anyPropertyId(), 0, inputContextId, 0);
		return winnerId == 0
				? memo.findWinner(groupId, memo.anyPropertyId(), 0, 0, 0)
				: winnerId;
	}

	private static void recordScalarPlans(PackedQuery query, PackedMemo memo, int ownerWinnerId, int scalarId,
			int inputContextId) {
		if (scalarId == 0) {
			return;
		}
		if (query.scalarOperator(scalarId) == PackedScalarOp.EXISTS) {
			int payloadId = query.scalarPayload(scalarId);
			if (query.payloadOperator(payloadId) == PackedPayloadOp.SUBQUERY_VALUE
					&& query.payloadChildCount(payloadId) == 1) {
				int subqueryRelationId = query.payloadChild(payloadId, 0);
				int groupId = memo.logicalGroupId(subqueryRelationId);
				int winnerId = inputContextId == 0
						? 0
						: memo.findWinner(groupId, memo.anyPropertyId(), 0, inputContextId, 0);
				if (winnerId == 0) {
					winnerId = memo.findWinner(groupId, memo.anyPropertyId(), 0, 0, 0);
				}
				if (winnerId != 0) {
					memo.putDependentPlan(ownerWinnerId, payloadId, winnerId);
				}
			}
		}
		for (int ordinal = 0; ordinal < query.scalarChildCount(scalarId); ordinal++) {
			recordScalarPlans(query, memo, ownerWinnerId, query.scalarChild(scalarId, ordinal), inputContextId);
		}
	}

	private static double saturatedAdd(double left, double right) {
		double result = left + right;
		return Double.isFinite(result) ? result : Double.MAX_VALUE;
	}

	private static double saturatedMultiply(double left, double right) {
		double result = left * right;
		return Double.isFinite(result) ? result : Double.MAX_VALUE;
	}
}
